import React, { useState, useEffect } from "react";
import { BASE_URL } from "../config";

function CustomerRegistrationForm({ selectedCustomer, onCreate, onUpdate }) {
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    customerType: "",
  });

  // When editing, load existing customer data
  useEffect(() => {
    if (selectedCustomer) {
      setFormData(selectedCustomer);
    }
  }, [selectedCustomer]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      let response;
      if (selectedCustomer) {
        // ✅ Update existing customer
        response = await fetch(`${BASE_URL}/api/customers/${selectedCustomer.id}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(formData),
        });

        if (response.ok) {
          const updated = await response.json();
          onUpdate(updated); // tell parent to update list
        }
      } else {
        // ✅ Create new customer
        response = await fetch(`${BASE_URL}/api/customers`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(formData),
        });

        if (response.ok) {
          const created = await response.json();
          onCreate(created); // tell parent to refresh
        }
      }

      // reset form after success
      setFormData({
        firstName: "",
        lastName: "",
        email: "",
        phoneNumber: "",
        customerType: "",
      });
    } catch (error) {
      console.error("Error saving customer:", error);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="form-container">
      <h2>{selectedCustomer ? "Update Customer" : "Register Customer"}</h2>
      <input type="text" name="firstName" placeholder="First Name"
        value={formData.firstName} onChange={handleChange} required />
      <input type="text" name="lastName" placeholder="Last Name"
        value={formData.lastName} onChange={handleChange} required />
      <input type="email" name="email" placeholder="Email"
        value={formData.email} onChange={handleChange} required />
      <input type="text" name="phoneNumber" placeholder="Phone Number"
        value={formData.phoneNumber} onChange={handleChange} />
      <select name="customerType" value={formData.customerType} onChange={handleChange}>
        <option value="">Select type</option>
        <option value="Premium">Premium</option>
        <option value="Standard">Standard</option>
      </select>

      <button type="submit">
        {selectedCustomer ? "Update" : "Register"}
      </button>
    </form>
  );
}

export default CustomerRegistrationForm;
